def enabled(spec):
    return spec.get('id')=='E42' and spec.get('execution_design',{}).get('revision')=='embodied50-execution-v3-20261102'


def central_reference(source_object,lateral=0.):
    """Actual front surface at a bounded tool-Y section, for engineering control."""
    edge_distance(TRIANGLES[0,0],source_object)  # strict source SHA/dimensions
    lateral=float(lateral)
    if not np.isfinite(lateral)or abs(lateral)>.020000001:
        raise ValueError('Reviewed source front section must remain within20mm of centre')
    crossings=[]
    for triangle in TRIANGLES:
        for a,b in zip(triangle,np.roll(triangle,-1,axis=0)):
            if abs(a[1]-lateral)<1e-12:crossings.append(a.copy())
            elif (a[1]-lateral)*(b[1]-lateral)<0:
                crossings.append(a+(b-a)*((lateral-a[1])/(b[1]-a[1])))
    if not crossings:raise ValueError('Source front rim does not cross its centre plane')
    point=max(crossings,key=lambda p:float(p[0])).copy();point[1]=lateral
    if edge_distance(point,source_object)>1e-9:raise ValueError('Actual centre reference must lie on the source front surface')
    return point


def edge_distance(local_point, source_object):
    if source_object.get('source_asset',{}).get('sha256')!=SOURCE_SHA:
        raise ValueError('E42 front rim source SHA mismatch')
    if not np.allclose(source_object['size'],SOURCE_HALF,atol=1e-10,rtol=0):
        raise ValueError('E42 front rim source dimensions mismatch')
    p=np.asarray(local_point,float)
    if p.shape!=(3,) or not np.isfinite(p).all():raise ValueError('Invalid E42 source-local contact point')
    a,b,c=TRIANGLES[:,0],TRIANGLES[:,1],TRIANGLES[:,2]
    ab=b-a;ac=c-a;ap=p-a
    aa=np.einsum('ij,ij->i',ab,ab);bb=np.einsum('ij,ij->i',ab,ac);cc=np.einsum('ij,ij->i',ac,ac)
    pa=np.einsum('ij,ij->i',ap,ab);pc=np.einsum('ij,ij->i',ap,ac);den=aa*cc-bb*bb
    u=(cc*pa-bb*pc)/den;w=(aa*pc-bb*pa)/den
    normals=np.cross(ab,ac);normals/=np.linalg.norm(normals,axis=1)[:,None]
    plane=np.abs(np.einsum('ij,ij->i',ap,normals));inside=(u>=0)&(w>=0)&(u+w<=1)
    distances=np.where(inside,plane,np.inf)
    for start,end in ((a,b),(b,c),(c,a)):
        delta=end-start;fraction=np.clip(np.einsum('ij,ij->i',p-start,delta)/np.einsum('ij,ij->i',delta,delta),0,1)
        distances=np.minimum(distances,np.linalg.norm(p-start-fraction[:,None]*delta,axis=1))
    return float(distances.min())
